window.docContents[199].resolve({"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Reasoning-About-Lists--Induction-on-Lists--Generalizing-Statements":{"contents":"In some situations, it is necessary to generalize a\nstatement in order to prove it by induction.  Intuitively, the\nreason is that a more general statement also yields a more general\n(stronger) inductive hypothesis.\n\n\n\ntheorem myRepeat_append {c n : Nat} :\n    myRepeat n c ++ myRepeat n c = myRepeat n (c + c) := by\n  induction c with\n  | zero => rw [repeat_zero, nil_append]\n  | succ c' ih =>\n    rw [repeat_succ]\n    -- Now we seem to be stuck.\n    -- The `ih` only works for `c' + c'`,\n    -- but we need `c' + 1 + (c' + 1)`.\ntheorem myRepeat_append {c n : Nat} :\n    myRepeat n c ++ myRepeat n c = myRepeat n (c + c) := by\n  induction c with\n  | zero => rw [repeat_zero, nil_append]\n  | succ c' ih =>\n    rw [repeat_succ]\n    -- Now we seem to be stuck.\n    -- The `ih` only works for `c' + c'`,\n    -- but we need `c' + 1 + (c' + 1)`.\ntheorem myRepeat_append {c n : Nat} :\n    myRepeat n c ++ myRepeat n c = myRepeat n (c + c) := by\n  induction c with\n  | zero => rw [repeat_zero, nil_append]\n  | succ c' ih =>\n    rw [repeat_succ]\n    -- Now we seem to be stuck.\n    -- The `ih` only works for `c' + c'`,\n    -- but we need `c' + 1 + (c' + 1)`.\n\n\nunsolved goals\ncase succ\nn c' : Nat\nih : myRepeat n c' ++ myRepeat n c' = myRepeat n (c' + c')\n⊢ (n :: myRepeat n c') ++ (n :: myRepeat n c') = myRepeat n (c' + 1 + (c' + 1))\n\n\nTo get a more general inductive hypothesis, we can generalize:\n\n\n\ntheorem myRepeat_append {c₁ c₂ n : Nat} :\n    myRepeat n c₁ ++ myRepeat n c₂ = myRepeat n (c₁ + c₂) := by\n  induction c₁ with\n  | zero =>\n    rw [repeat_zero, Nat.zero_add, nil_append]\n  | succ c1' ih =>\n    rw [Nat.succ_add, repeat_succ, repeat_succ, cons_append, ih]\ntheorem myRepeat_append {c₁ c₂ n : Nat} :\n    myRepeat n c₁ ++ myRepeat n c₂ = myRepeat n (c₁ + c₂) := by\n  induction c₁ with\n  | zero =>\n    rw [repeat_zero, Nat.zero_add, nil_append]\n  | succ c1' ih =>\n    rw [Nat.succ_add, repeat_succ, repeat_succ, cons_append, ih]\ntheorem myRepeat_append {c₁ c₂ n : Nat} :\n    myRepeat n c₁ ++ myRepeat n c₂ = myRepeat n (c₁ + c₂) := by\n  induction c₁ with\n  | zero =>\n    rw [repeat_zero, Nat.zero_add, nil_append]\n  | succ c1' ih =>\n    rw [Nat.succ_add, repeat_succ, repeat_succ, cons_append, ih]\n\n\n","context":"Logical Foundations\u0009Lists: Working with Structured Data\u0009Reasoning About Lists\u0009Induction on Lists","header":"5.3.1.1. Generalizing Statements","id":"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Reasoning-About-Lists--Induction-on-Lists--Generalizing-Statements"}});